import{_ as e,o,c as r,a2 as a}from"./chunks/framework.BXzK3EA4.js";const n="/assets/268_0b00b4eb-60d9-44e6-85c8-a9195a1f3662.r78IJWzJ.png",h=JSON.parse('{"title":"How to Monitor Network Traffic on a Physical Server","description":"","frontmatter":{"title":"How to Monitor Network Traffic on a Physical Server"},"headers":[],"relativePath":"operations-knowledge-base/dedicated-server/how-to-monitor-network-traffic-on-a-physical-server.md","filePath":"operations-knowledge-base/dedicated-server/how-to-monitor-network-traffic-on-a-physical-server.md","lastUpdated":1794292919000}'),i={name:"operations-knowledge-base/dedicated-server/how-to-monitor-network-traffic-on-a-physical-server.md"};function s(c,t,u,f,l,d){return o(),r("div",null,[...t[0]||(t[0]=[a('<h2 id="i-overview" tabindex="-1">I. Overview <a class="header-anchor" href="#i-overview" aria-label="Permalink to &quot;I. Overview&quot;">​</a></h2><p>The network monitoring feature provides visualized monitoring of server network traffic. Through intuitive traffic graphs, you can clearly view incoming and outgoing traffic across different time periods. This helps you stay informed of the server’s network status and provides useful data for network resource planning, troubleshooting, and performance optimization.</p><hr><h2 id="ii-access-path" tabindex="-1">II. Access Path <a class="header-anchor" href="#ii-access-path" aria-label="Permalink to &quot;II. Access Path&quot;">​</a></h2><p>Log in to the platform and go to the <strong>&quot;Customer Center&quot;</strong>. Under <strong>&quot;My Orders&quot;</strong>, click <strong>&quot;Physical Servers&quot;</strong>. Alternatively, go to <strong>&quot;Product Management&quot;</strong>, click <strong>&quot;Physical Servers&quot;</strong>, and filter the server list by region and status. In the product list, locate the target server and open the product details page. Then click the <strong>&quot;Network Monitoring&quot;</strong> tab at the top to enter the network monitoring interface.</p><p><img src="'+n+'" alt=""></p><h2 id="iii-interface-and-function-description" tabindex="-1">III. Interface and Function Description <a class="header-anchor" href="#iii-interface-and-function-description" aria-label="Permalink to &quot;III. Interface and Function Description&quot;">​</a></h2><h3 id="a-traffic-graph-area" tabindex="-1">(A) Traffic Graph Area <a class="header-anchor" href="#a-traffic-graph-area" aria-label="Permalink to &quot;(A) Traffic Graph Area&quot;">​</a></h3><ul><li><p><strong>Time Range Selection:</strong> Above the traffic graph, the <strong>&quot;period&quot;</strong> options include <strong>&quot;1h&quot;</strong>, <strong>&quot;2h&quot;</strong>, <strong>&quot;3h&quot;</strong>, <strong>&quot;6h&quot;</strong>, <strong>&quot;12h&quot;</strong>, <strong>&quot;1d&quot;</strong>, <strong>&quot;3d&quot;</strong>, <strong>&quot;7d&quot;</strong>, <strong>&quot;14d&quot;</strong>, <strong>&quot;1m&quot;</strong>, and <strong>&quot;all&quot;</strong>. You can select different time ranges to view traffic data for a specific period. You can also define a custom time range on the right side to view traffic data for a particular time interval.</p></li><li><p><strong>Traffic Trend Display:</strong> The traffic graph displays network traffic trends using line charts. Different colored lines represent different traffic types:</p><ul><li><strong>&quot;Incoming traffic on interface [average]&quot;</strong> — average incoming traffic on the network interface.</li><li><strong>&quot;Outgoing traffic on interface [average]&quot;</strong> — average outgoing traffic on the network interface.</li><li><strong>&quot;Inbound 95th Percentile&quot;</strong> — 95th percentile of inbound traffic.</li><li><strong>&quot;Outbound 95th percentile&quot;</strong> — 95th percentile of outbound traffic.</li><li><strong>&quot;Inbound + Outbound 95th percentile&quot;</strong> — sum of inbound and outbound 95th percentile traffic.</li></ul></li></ul><h3 id="b-traffic-statistics-information" tabindex="-1">(B) Traffic Statistics Information <a class="header-anchor" href="#b-traffic-statistics-information" aria-label="Permalink to &quot;(B) Traffic Statistics Information&quot;">​</a></h3><p>Below the traffic graph, key statistical data such as <strong>&quot;up to date&quot;</strong>, <strong>&quot;average&quot;</strong>, and <strong>&quot;maximum&quot;</strong> values are displayed for each traffic type. These indicators help you quickly understand the current network traffic status and usage patterns.</p><hr><h2 id="iv-usage-value" tabindex="-1">IV. Usage Value <a class="header-anchor" href="#iv-usage-value" aria-label="Permalink to &quot;IV. Usage Value&quot;">​</a></h2><ul><li><strong>Network Resource Planning:</strong> By analyzing long-term traffic monitoring data, you can identify traffic patterns and peak usage periods. This allows you to plan network resources appropriately and avoid service interruptions caused by insufficient bandwidth.</li><li><strong>Troubleshooting:</strong> When network anomalies occur (such as sudden spikes or drops in traffic), the network monitoring feature helps you quickly identify the affected time period and traffic type, providing useful insights for troubleshooting.</li><li><strong>Performance Optimization:</strong> Based on traffic monitoring data, you can optimize server network configurations and application deployments to improve overall network performance and service experience.</li></ul>',14)])])}const p=e(i,[["render",s]]);export{h as __pageData,p as default};
